// Attribute each chunk's bytes to source modules/packages via sourcemap (raw generated bytes, approximate).
import fs from 'node:fs'; import path from 'node:path';
const dist = process.argv[2]; const names = process.argv.slice(3);
function vlq(str){const c='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';const r=[];let shift=0,val=0;for(const ch of str){const d=c.indexOf(ch);val+=(d&31)<<shift;if(d&32){shift+=5}else{r.push(val&1?-(val>>1):val>>1);shift=0;val=0}}return r}
for (const n of names) {
  const f = n.endsWith('.js')?n:fs.readdirSync(path.join(dist,'assets')).find(x=>x.startsWith(n+'-')&&x.endsWith('.js')); if(!f){console.log(n,'missing');continue}
  const code = fs.readFileSync(path.join(dist,'assets',f),'utf8').split('\n'); const map = JSON.parse(fs.readFileSync(path.join(dist,'assets',f+'.map'),'utf8'));
  const by = {}; let srcIdx=0; const lines = map.mappings.split(';');
  for (let li=0; li<lines.length; li++) { const segs = lines[li]?lines[li].split(','):[]; let col=0; const pts=[];
    for (const s of segs) { if(!s)continue; const v=vlq(s); col+=v[0]; if(v.length>1){srcIdx+=v[1]; pts.push([col,srcIdx])} }
    // (source index delta is cumulative across lines per spec)
    const len = (code[li]||'').length; for (let i=0;i<pts.length;i++){ const end = i+1<pts.length?pts[i+1][0]:len; const sz = Math.max(0,end-pts[i][0]); let src = map.sources[pts[i][1]]||'?';
      const m = src.match(/node_modules\/(?:\.pnpm\/[^/]+\/node_modules\/)?((?:@[^/]+\/)?[^/]+)/); const key = m? m[1] : (src.includes('packages/ui/')?'@runly/ui:'+(src.split('packages/ui/src/')[1]||'').split('/').slice(0,2).join('/') : src.includes('apps/desktop/src')? 'app:'+(src.split('apps/desktop/src/')[1]||'').split('/').slice(0,2).join('/') : src.replace(/^(\.\.\/)+/,'').split('/').slice(0,2).join('/'));
      by[key]=(by[key]||0)+sz; } }
  const tot = Object.values(by).reduce((a,b)=>a+b,0);
  console.log(`\n${f} generated~${(tot/1024).toFixed(0)}KB`); Object.entries(by).sort((a,b)=>b[1]-a[1]).slice(0,14).forEach(([k,v])=>console.log('  ',k.padEnd(48),(v/1024).toFixed(0).padStart(6),'KB'));
}
